.ui-treeDropdown {
  position: relative;
}
.ui-treeDropdown-with-label {
  margin-top: 29px;
}
.ui-treeDropdown-wrapper {
  position: relative;
}
.ui-treeDropdown-wrapper input {
  padding: 0 26px 0 8px;
  font-family: var(--vscode-font-family);
}
.ui-treeDropdown-wrapper.disabled > button {
  z-index: -1;
}
.ui-treeDropdown-wrapper.readonly > button {
  pointer-events: none;
}
.ui-treeDropdown-caret {
  position: absolute;
  width: 24px;
  height: 24px;
  top: 0;
  right: 0;
  cursor: pointer;
  box-sizing: border-box;
}
.ui-treeDropdown-caret:hover, .ui-treeDropdown-caret:active, .ui-treeDropdown-caret:focus {
  background-color: transparent;
}
.ui-treeDropdown label {
  position: absolute;
  bottom: 26px;
  margin-top: 0 !important;
  font-family: var(--vscode-font-family);
  font-size: 13px;
  font-weight: bold;
  box-sizing: border-box;
  box-shadow: none;
  margin-right: 0px;
  margin-bottom: 0px;
  margin-left: 0px;
  display: block;
  padding: 4px 0;
  overflow-wrap: break-word;
}
.ui-treeDropdown label.required:after {
  content: " *";
  color: var(--vscode-inputValidation-errorBorder);
}
.ui-treeDropdown label.disabled {
  opacity: 0.4;
}
