@keyframes delayedFadeOut {
  0% {
    opacity: 1;
  }
  99% {
    opacity: 0;
    visibility: visible;
  }
  100% {
    visibility: hidden;
  }
}
.section {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.section__header > div {
  flex: 0 1 auto;
  background: var(--vscode-sideBarSectionHeader-background);
  min-height: 40px;
  display: flex;
  align-items: center;
  padding: 0 1rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: var(--vscode-sideBarTitle-foreground);
}
.section__header__title {
  width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
}
.section__header__title.ui-medium-header {
  line-height: normal;
}
.section__body {
  margin: 1rem 0.75rem;
  flex: 1 1 auto;
  padding: 0 0.25rem;
  height: 100%;
}
.section__body > .ui-loader-blocker:before {
  z-index: 1;
}
.section--clean .section__body {
  margin: 0;
  padding: 0;
}
.section--scrollable .section__body {
  overflow: auto;
}
.section--extended .section__header {
  background-color: var(--vscode-sideBar-background);
}
.section__collapse {
  position: absolute;
  top: 0;
  left: 0;
  width: 13px;
}
.section--hidden {
  animation: 0.5s delayedFadeOut;
  animation-fill-mode: forwards;
}
