.ui-toolbar {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 20;
}
.ui-toolbar__container {
  overflow-x: scroll;
}
.ui-toolbar__content {
  border-bottom: 1px solid var(--vscode-contrastBorder, var(--vscode-editorIndentGuide-background));
  background-color: var(--vscode-editor-background);
  display: flex;
  flex-wrap: wrap;
  min-width: 400px;
}
.ui-toolbar .ui-divider {
  display: inline-block;
  height: 20px;
  margin: 3px 10px 3px;
  border-right: 1px solid var(--vscode-contrastBorder, var(--vscode-editorIndentGuide-background));
}
.ui-toolbar__column {
  display: flex;
  flex-grow: 1;
}
.ui-toolbar__column__content {
  display: flex;
  margin: 6px 20px 6px;
  height: 28px;
}

@media screen and (max-width: 640px) {
  .ui-toolbar .ui-toolbar__content {
    flex-wrap: wrap;
  }
  .ui-toolbar div.ui-divider.hidden-xs {
    display: none;
  }
}
