:root {
  --ui-box-shadow-small: 0 4px 8px 0 var(--vscode-widget-shadow);
  --ui-box-shadow-medium: 0 6px 12px 0 var(--vscode-widget-shadow);
  --ui-box-shadow-large: 0 10px 20px 0 var(--vscode-widget-shadow);
}

.ui-box-shadow-small {
  box-shadow: var(--ui-box-shadow-small);
}

.ui-box-shadow-medium {
  box-shadow: var(--ui-box-shadow-medium);
}

.ui-box-shadow-large {
  box-shadow: var(--ui-box-shadow-large);
}

.uiLoaderXLarge .ms-Spinner-circle {
  width: 50px;
  height: 50px;
}

.uiLoaderXSmall .ms-Spinner-circle {
  border-width: 1px;
  width: 12px;
  height: 12px;
}

.ui-loader--delayed {
  opacity: 0;
  animation: 1s ease-in 0.3s normal forwards 1 ui-loader-fade-in;
  z-index: 1;
}

@keyframes ui-loader-fade-in {
  0% {
    opacity: 0;
  }
  100% {
    opacity: 1;
  }
}
