.ui-toggle-group-option {
  height: 22px;
  min-width: 22px;
  border-radius: 2px;
  font-style: normal;
  font-weight: 700;
  font-size: 13px;
  line-height: 18px;
  display: flex;
  align-items: center;
  text-align: center;
  justify-content: center;
  color: var(--vscode-foreground);
  border: none;
  background-color: transparent;
  position: relative;
}
.ui-toggle-group-option:not(:last-child) {
  margin: 0 3px 0 0;
}
.ui-toggle-group-option:hover {
  cursor: pointer;
  background-color: var(--vscode-menubar-selectionBackground);
  outline: 1px dashed var(--vscode-contrastActiveBorder);
}
.ui-toggle-group-option:focus {
  border-radius: 0;
  outline: transparent;
}
.ui-toggle-group-option--focused:focus-visible::after {
  content: "";
  position: absolute;
  border: none;
  z-index: 1;
  outline: 1px solid var(--vscode-contrastActiveBorder, var(--vscode-button-background));
  inset: -1px;
}
.ui-toggle-group-option--selected {
  background-color: var(--vscode-button-background);
  color: var(--vscode-button-foreground);
  outline: 1px solid var(--vscode-contrastActiveBorder);
}
.ui-toggle-group-option--selected:hover {
  background-color: var(--vscode-button-hoverBackground);
  outline: 1px dashed var(--vscode-contrastActiveBorder);
}
.ui-toggle-group-option--selected .ui-toggle-group-option-content-icon svg > path,
.ui-toggle-group-option--selected .ui-toggle-group-option-content-icon svg > rect {
  fill: var(--vscode-button-foreground);
}
.ui-toggle-group-option--disabled {
  opacity: 0.5;
  background-color: transparent;
}
.ui-toggle-group-option--disabled:hover {
  background-color: transparent;
  cursor: initial;
}
.ui-toggle-group-option-content-icon {
  display: flex;
}
