.ui-DatePicker {
  display: flex;
  align-items: center;
  height: 24px;
  max-height: 24px;
  min-height: 24px;
  margin: 0;
}

.ui-DatePicker-toggle {
  position: relative;
  margin-left: 10px;
}
.ui-DatePicker-toggle input {
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  cursor: pointer;
}
.ui-DatePicker-toggle input::-webkit-calendar-picker-indicator {
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  cursor: pointer;
}

body[data-vscode-theme-kind=vscode-dark] .ui-DatePicker-toggle input {
  color-scheme: dark;
}
