.sections {
  position: relative;
  overflow: hidden;
}
.sections--horizontal {
  height: 100%;
}
.sections--horizontal .sections__item {
  height: 100%;
}
.sections--vertical {
  width: 100%;
}
.sections--vertical .sections__item {
  width: 100%;
}
.sections .sections__item {
  position: absolute;
}
.sections--animated .sections__item {
  transition: all 300ms ease 0s;
}
.sections--animated.sections--horizontal .sections__item {
  transition-property: transform, left, right;
}
.sections--animated.sections--vertical .sections__item {
  transition-property: transform, top, bottom;
}
.sections.sections--horizontal .sections__item--toggle.sections__item--hidden {
  transform: translateX(100%);
}
.sections.sections--horizontal .sections__item--toggle {
  max-width: calc(100% - 24px);
}
.sections.sections--horizontal > .sections__item:first-child {
  padding-right: 7px;
}
.sections.sections--vertical .sections__item--toggle.sections__item--hidden {
  transform: translateY(100%);
}
.sections.sections--vertical .sections__item--toggle {
  max-height: calc(100% - 24px);
}
